// Function to compute the sum of a list of numbers using async/await
async function sumAsync(numbers) {
  // Check if the input is an array
  if (!Array.isArray(numbers)) {
    throw new Error('Input should be an array');
  }

  // Use async/await to compute the sum in parallel
 const sum = numbers.reduce((acc, num) => acc + num, 0);

  return sum;
}

// Example usage
const input = [1, 2, 3, 4, 5];
console.log(await sumAsync(input)); // Output: 15

// You can also use async/await with a synchronous input list
const input2 = [1, 2, 3, 4, 5];
console.log(sumAsync(input2)); // Output: 15
```

